import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import MemberList from '../../common/MemberList';
import MemberView from '../../common/MemberView';
import LogView from '../../common/LogView';

/*
 * The forum's Member Desk for staff who can't open the admin (moderators by default). One lazy
 * chunk: nobody else ever downloads it.
 */

class DeskPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.bodyClass = 'MemberDeskForumPage';
    app.history.push('member-desk', app.translator.trans('ernestdefoe-member-desk.forum.title'));
    app.setTitle(app.translator.trans('ernestdefoe-member-desk.forum.title'));
  }
  view() {
    const can = app.forum.attribute('memberDesk');
    return m("div", {
      className: "MemberDeskForum"
    }, m("div", {
      className: "container"
    }, m("h1", {
      className: "MemberDeskForum-title"
    }, app.translator.trans('ernestdefoe-member-desk.forum.title')), can?.view ? this.body() : m("p", {
      className: "MemberDesk-error"
    }, app.translator.trans('ernestdefoe-member-desk.forum.no_access'))));
  }
}
export class ForumListPage extends DeskPage {
  body() {
    return m(MemberList, null);
  }
}
export class ForumMemberPage extends DeskPage {
  body() {
    return m(MemberView, {
      id: Number(m.route.param('id'))
    });
  }
}
export class ForumLogPage extends DeskPage {
  body() {
    return m(LogView, null);
  }
}
flarum.reg.add('ernestdefoe-member-desk', 'forum/components', null);